let horizontalMouseDown=!1,verticalMouseDown=!1;const root=document.documentElement,resize=document.getElementById("divider"),verticalDivider=document.getElementById("verticalDivider"),browser=document.getElementById("browser");verticalDivider.addEventListener("pointerdown",e=>{verticalMouseDown=!0,verticalDivider.setPointerCapture(e.pointerId)}),resize.addEventListener("pointerdown",e=>{horizontalMouseDown=!0,resize.setPointerCapture(e.pointerId)}),document.addEventListener("pointermove",e=>{if(horizontalMouseDown){e.preventDefault();const t=window.innerWidth;root.style.setProperty("--inWidth",`clamp(6px, ${e.clientX/t*100}%, calc(100% - 5px))`)}if(verticalMouseDown){e.preventDefault();const t=browser.clientHeight;root.style.setProperty("--height",`clamp(0px, calc(${e.clientY} / ${t} * 100% - 87px), calc(100% - 12px))`)}}),document.addEventListener("pointerup",e=>{horizontalMouseDown&&resize.releasePointerCapture(e.pointerId),verticalMouseDown&&verticalDivider.releasePointerCapture(e.pointerId),horizontalMouseDown=!1,verticalMouseDown=!1});
